 report={'actor_type':'automated','actor_id':'codex-independent-se-ifa-peer','generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_id':source['id'],'source_sha256':source['sha256'],'candidate_path':str(candidate_path.relative_to(ROOT)),'candidate_sha256':sha(raw),'frozen_source_first_inventory_sha256':sha(frozen_raw),'independent_physical_body_cells':frozen['physical_body_cells'],'independent_primary_occurrences':frozen['native_occurrences'],'independent_empty_surfaces':len(frozen['empty_surfaces']),'independent_header_surfaces':len(frozen['explicit_header_surfaces']),'matched_records':len(matches),'runtime_loader_accepted':len(loaded),'formal_schema_passed':len(final)if not schema_errors else 0,'checks':len(checks),'errors':errors,'negative_controls':negatives,'occurrence_matches':matches,'passed':not errors,'MF_core_cache_publication_modified':False,'acceptance_scope':'Only the exact40page primary physical IFA fields; not whole571pageSource, UF closure or pedagogical/human review.'};(OUT/'verification.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(report['passed'],len(checks),len(errors),len(matches),len(loaded),len(schema_errors));print(json.dumps(errors[:5],ensure_ascii=False,indent=2))
